 save('affected-inventory.json',{'affected_questions':[]})
 save('scope-results.json',{'requested_difficulty':'easy','independent_samples':dict(Counter(r['generation']['difficulty'] for r in raw)),'reasoning':'Easy uses one row swap or nonzero scaling with exact integer results in sampled banks; moderate one addition; hard two sequential operations. No solving systems, selecting operations, or other unsupported prerequisite introduced.','source_support':['q-130070','q-130071','q-10217','q-130072','q-72786','q-72785'],'check':'Prompts independently parsed and final matrices checked in math-results.json. Source completeness remains separately failed.','observed_easy_factor_count':len(coverage['raw']['scale']['scalars']),'observed_easy_shapes':sorted({str((len(r['generation']['instance']['matrix']),len(r['generation']['instance']['matrix'][0]))) for r in raw if r['generation']['difficulty']=='easy'})})
